# Replaces the hook generated by linuxdeploy-plugin-gstreamer (same file name, copied over it).
#
# Why: the stock hook locates its helpers with `find` and ends with `[ -n ... ] && export`,
# which evaluates false when a helper is missing. AppRun runs with `set -e`, so on a system
# without `find` (minimal openSUSE, some containers) the AppImage exited silently with code 1.
# This version uses fixed paths, never depends on external tools, and always succeeds.

export GST_REGISTRY_REUSE_PLUGIN_SCANNER="no"
export GST_PLUGIN_SYSTEM_PATH_1_0="${APPDIR}/usr/lib/gstreamer-1.0"
export GST_PLUGIN_PATH_1_0="${APPDIR}/usr/lib/gstreamer-1.0"
unset GST_PLUGIN_PATH GST_PLUGIN_SYSTEM_PATH   # never mix in the host's plugins

_ht_gst_helpers="${APPDIR}/usr/lib/gstreamer1.0/gstreamer-1.0"
if [ -x "$_ht_gst_helpers/gst-plugin-scanner" ]; then
  export GST_PLUGIN_SCANNER_1_0="$_ht_gst_helpers/gst-plugin-scanner"
fi
if [ -x "$_ht_gst_helpers/gst-ptp-helper" ]; then
  export GST_PTP_HELPER_1_0="$_ht_gst_helpers/gst-ptp-helper"
fi

# Keep our own plugin registry so the host's GStreamer cache is never touched or confused.
_ht_cache="${XDG_CACHE_HOME:-${HOME:-/tmp}/.cache}/hop-tunes"
mkdir -p "$_ht_cache" 2>/dev/null || _ht_cache="${TMPDIR:-/tmp}"
export GST_REGISTRY_1_0="$_ht_cache/gstreamer-registry.x86_64.bin"

unset _ht_gst_helpers _ht_cache
true
